def _refused_on(feature: Feature, rule: Rule, dialects: list[str]) -> None:
    """Each of ``dialects`` keeps the old table's form in ``rule`` or is native there: a row that
    writes its own form is not refused outright."""
    for dialect in dialects:
        form = rule.forms.get(dialect)
        if form is not KEPT and form is not None:
            raise RuleError(
                f"{feature.name} {rule.pattern}: measured refuses it on {dialect}, where"
                " the row writes its own form"
            )


def _stated_side(feature: Feature) -> Side:
    side = feature.read
    rules = []
    limitations = {d: list(lims) for d, lims in side.limitations.items()}
    for rule in side.rules:
        key = (feature.name, rule.pattern or "")
        forms = dict(rule.forms)
        for message, dialects, _call in REFUSED.get(key, ()):
            _refused_on(feature, rule, dialects.split())
            forms.update({d: Refusal("0A000", message.format(dialect=d)) for d in dialects.split()})
        for sqlstate, message, dialects, text, _call in LIMITED.get(key, ()):
            for d in dialects.split():
                refusal = Refusal(sqlstate, message.format(dialect=d))
                limitations.setdefault(d, []).append(Limitation(text, refusal))
        rules.append(replace(rule, forms=forms))
    for dialects, text in BOUNDED.get(feature.name, ()):
        for d in dialects.split():
            limitations.setdefault(d, []).append(Limitation(text))
    return replace(
        side, rules=tuple(rules), limitations={d: tuple(v) for d, v in limitations.items()}
    )


def stated(features: tuple[Feature, ...]) -> tuple[Feature, ...]:
    """``features``, each row stating the translator's refusals of its calls."""
    named = {(f.name, r.pattern or "") for f in features for r in f.read.rules}
    listed = REFUSED.keys() | LIMITED.keys()
    unknown = sorted(listed - named) + sorted(BOUNDED.keys() - {f.name for f in features})
    if unknown:
        raise RuleError(f"measured names rows the grid has not: {unknown}")
    return tuple(
        replace(feature, read=_stated_side(feature))
        if feature.name in BOUNDED
        or any((feature.name, r.pattern or "") in listed for r in feature.read.rules)
        else feature
        for feature in features
    )
